package com.ias.finance;
import org.junit.jupiter.api.*;
import org.h2.tools.RunScript;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.ias.finance.JdbcMoneyLedger.*;

class FeeCompletionMirrorTest {
 QuoteSourcesTest f;FeeCompletionMirror mirror;TrustedFeeCompletion.Verified verified;Map<String,Object> fact;UUID completion=UUID.randomUUID();
 @BeforeEach void setup()throws Exception{f=new QuoteSourcesTest();f.setup();f.details=new JdbcFeeGroups.QuoteDetails(false,"已完成免费方案的真实审批记录组件夹具",f.details.kinds());f.f.store.submit(f.f.actor,f.f.owner,f.command,f.details);try(var db=f.f.source.getConnection()){RunScript.execute(db,new InputStreamReader(getClass().getResourceAsStream("/db/migration/V7__approval_completion_mirror.sql"),StandardCharsets.UTF_8));}fact=new HashMap<>(Map.of("tenantId","1","companyId","2","groupId",f.f.owner.faultGroupId().toString(),"completionId",completion.toString(),"actorUserId","90","state","COMPLETED","quoteId",f.command.applicationId().toString(),"quoteVersion","1","checkedAt",Instant.now().toString()));fact.put("financeReceiptId",UUID.randomUUID().toString());verified=new TrustedFeeCompletion.Verified(UUID.randomUUID(),completion,f.f.store.quote(f.f.actor,f.f.owner,f.command.applicationId()),fact);mirror=new FeeCompletionMirror(f.f.source);}
 Map<String,Object> group(){return Map.of("tenantId","1","companyId","2","groupId",f.f.owner.faultGroupId().toString(),"completions",List.of(fact));}
 @Test void originalCompletionRecordsHighWaterAndAuditOnceWithoutActorSession()throws Exception{var result=mirror.record(f.f.owner,verified);assertEquals("250000",result.get("highestApprovedCents"));assertTrue((Boolean)result.get("everRequiredFinance"));assertEquals("2",result.get("groupVersion"));assertEquals(result,mirror.record(f.f.owner,verified));assertEquals(1,f.f.count("finance_approval_completion_mirror"));assertEquals(1,f.f.count("finance_approval_fact"));assertEquals(250000,f.f.store.read(f.f.actor,f.f.owner).highestApprovedCents());try(var db=f.f.source.getConnection();var q=query(db,"SELECT actor_id FROM finance_audit WHERE operation_id=?",FeeCompletionMirror.operation(f.f.owner,completion).toString());var r=q.executeQuery()){assertTrue(r.next());assertEquals(90,r.getLong(1));}}
 @Test void missingMirrorBlocksNewBasisThenOriginalMirrorUnblocks()throws Exception{try(var db=f.f.source.getConnection()){assertThrows(com.ias.trust.Problem.class,()->FeeCompletionMirror.highWater(db,f.f.owner,group()));}mirror.record(f.f.owner,verified);try(var db=f.f.source.getConnection()){FeeCompletionMirror.highWater(db,f.f.owner,group());}assertEquals(2,f.f.store.read(f.f.actor,f.f.owner).version());}
 @Test void auditFailureRollsBackMirrorHighWaterAndOriginalKeyRecovers()throws Exception{try(var db=f.f.source.getConnection();var s=db.createStatement()){s.execute("ALTER TABLE finance_audit ADD CONSTRAINT mirror_audit_fault CHECK(action_name<>'APPROVAL_RECORDED')");}assertThrows(SQLException.class,()->mirror.record(f.f.owner,verified));assertEquals(0,f.f.count("finance_approval_completion_mirror"));assertEquals(0,f.f.store.read(f.f.actor,f.f.owner).highestApprovedCents());try(var db=f.f.source.getConnection();var s=db.createStatement()){s.execute("ALTER TABLE finance_audit DROP CONSTRAINT mirror_audit_fault");}mirror.record(f.f.owner,verified);assertEquals(1,f.f.count("finance_approval_completion_mirror"));}
 @Test void changedFactsConflictAndLaterLowQuoteNeverLowersHighWater()throws Exception{mirror.record(f.f.owner,verified);fact.put("actorUserId","91");assertThrows(com.ias.trust.Problem.class,()->mirror.record(f.f.owner,verified));fact.put("actorUserId","90");var next=f.f.command(2,100,900000,Set.of(f.command.additions().getFirst().id()));f.f.store.submit(f.f.actor,f.f.owner,next,f.f.details(next));assertEquals(250000,f.f.store.read(f.f.actor,f.f.owner).highestApprovedCents());assertTrue(f.f.store.read(f.f.actor,f.f.owner).everRequiredFinance());}
 @Test void concurrentMirrorHasOneReceiptAndOneVersionIncrement()throws Exception{try(var pool=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()){var gate=new java.util.concurrent.CountDownLatch(1);var jobs=new ArrayList<java.util.concurrent.Future<Map<String,Object>>>();for(int n=0;n<6;n++)jobs.add(pool.submit(()->{gate.await();return mirror.record(f.f.owner,verified);}));gate.countDown();var first=jobs.getFirst().get();for(var job:jobs)assertEquals(first,job.get());}assertEquals(1,f.f.count("finance_approval_completion_mirror"));assertEquals(2,f.f.store.read(f.f.actor,f.f.owner).version());}
 @Test void quoteWaitsForHighWaterAndStaleOriginalParametersRequireExplicitAbort()throws Exception{
  var guard=new QuoteSourcesTest.Wrapped(f.f.authority){public void approvalHighWater(Connection db,JdbcFeeGroups.Actor a,FeeGroup.Identity owner)throws SQLException{FeeCompletionMirror.highWater(db,owner,group());}};
  var store=new JdbcFeeGroups(f.f.source,guard);var next=f.f.command(1,100,900000,Set.of(f.command.additions().getFirst().id()));var details=f.f.details(next);
  assertThrows(com.ias.trust.Problem.class,()->store.submit(f.f.actor,f.f.owner,next,details));assertEquals(1,f.f.count("finance_quote_version"));assertEquals("IN_PROGRESS",new JdbcQuoteSources(f.f.source,f.f.authority).read(f.f.actor,f.f.owner,next.operationId()).state());
  mirror.record(f.f.owner,verified);assertThrows(IllegalStateException.class,()->store.submit(f.f.actor,f.f.owner,next,details));assertEquals(1,f.f.count("finance_quote_version"));
  new JdbcQuoteSources(f.f.source,f.f.authority).abort(f.f.actor,f.f.owner,next.operationId(),next.applicationId(),1,JdbcFeeGroups.quoteDigest(f.f.owner,next,details),"H事实同步后旧版本明确终止再重新报价");
  var fresh=f.f.command(2,100,900000,Set.of(f.command.additions().getFirst().id()));var result=store.submit(f.f.actor,f.f.owner,fresh,f.f.details(fresh));assertEquals(250000,result.basis().hCents());assertTrue(result.basis().financialReviewRequired());
 }
}
